window.CHAPTER_LOCAL=window.CHAPTER_LOCAL||{};window.CHAPTER_LOCAL["lonelylands"]=JSON.parse("{\n  \"id\": \"lonelylands\",\n  \"title\": \"Одинокие земли\",\n  \"roman\": \"III\",\n  \"startSteps\": 289333,\n  \"startKm\": 217,\n  \"totalKm\": 169,\n  \"totalSteps\": 225334,\n  \"endSteps\": 514667,\n  \"stepMeters\": 0.75,\n  \"source\": {\n    \"file\": \"route-master.xlsx\",\n    \"sha256\": \"a93611798140021a39fda53dedc05cc1a5f2147a375a80e35634f40c52eb5c50\",\n    \"sheet\": \"3. Одинокие земли\",\n    \"thresholds\": \"global, column I\",\n    \"textColumn\": \"L\",\n    \"versionEvidence\": \"20/22 populated events; 100/169 km; CAVE-01/02. Workbook metadata has no version label.\"\n  },\n  \"segments\": [\n    {\n      \"id\": 12,\n      \"from\": \"Бри\",\n      \"to\": \"Северные холмы\",\n      \"km\": 28,\n      \"startSteps\": 289333,\n      \"endSteps\": 326667,\n      \"geographicStatus\": \"Проверить\",\n      \"geographicNote\": \"«Северные холмы» — авторский ориентир; не путать с Северным нагорьем Арнора.\"\n    },\n    {\n      \"id\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"km\": 33,\n      \"startSteps\": 326667,\n      \"endSteps\": 370667,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Точка входа в топи условна.\"\n    },\n    {\n      \"id\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"km\": 52,\n      \"startSteps\": 370667,\n      \"endSteps\": 440000,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Пустоши — общая область, координаты ещё не выбраны.\"\n    },\n    {\n      \"id\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"km\": 56,\n      \"startSteps\": 440000,\n      \"endSteps\": 514667,\n      \"geographicStatus\": \"Черновик\",\n      \"geographicNote\": \"Отметка «пустоши» условна.\"\n    }\n  ],\n  \"events\": [\n    {\n      \"id\": \"lonelylands-001\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 1,\n      \"title\": \"Окрестности Бри\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 12,\n      \"from\": \"Брыль\",\n      \"to\": \"Северные холмы\",\n      \"segmentKm\": 7,\n      \"km\": 224,\n      \"steps\": 298667,\n      \"stepsSincePrevious\": 9334,\n      \"text\": \"За последними домами Бри дорога становится всё тише, а у обочины возница безуспешно подтягивает ремень упряжи. За небольшую помощь он подсказывает, какой тропы лучше держаться дальше.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-001.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-001-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-002\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 2,\n      \"title\": \"Дорога сквозь лес\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 12,\n      \"from\": \"Брыль\",\n      \"to\": \"Северные холмы\",\n      \"segmentKm\": 14,\n      \"km\": 231,\n      \"steps\": 308000,\n      \"stepsSincePrevious\": 9333,\n      \"text\": \"Дорога скрывается под сенью деревьев, и солнечные пятна скользят по влажной земле. Между стволами на мгновение появляется олениха, оставив на тропе тонкие следы копыт.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-002.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-002-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-003\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 3,\n      \"title\": \"Старый межевой камень\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 12,\n      \"from\": \"Брыль\",\n      \"to\": \"Северные холмы\",\n      \"segmentKm\": 21,\n      \"km\": 238,\n      \"steps\": 317333,\n      \"stepsSincePrevious\": 9333,\n      \"text\": \"Старый межевой камень почти целиком зарос лишайником, но под ним ещё угадывается знак Северного королевства. У его подножия находится потемневшая медная монета — маленький осколок далёкого прошлого.\",\n      \"reward\": {\n        \"id\": \"lonelylands-003-reward\",\n        \"name\": \"Знак Арнора\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Знак Арнора\",\n        \"badgePrompt\": \"Старинная медная монета Северного королевства со стёртой звездой и геометрическим ободком, пятна времени и патины.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Знак Арнора\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Старинная медная монета Северного королевства со стёртой звездой и геометрическим ободком, пятна времени и патины.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-003.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-003-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-004\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 4,\n      \"title\": \"Северные холмы\",\n      \"type\": \"Локация\",\n      \"segment\": 12,\n      \"from\": \"Брыль\",\n      \"to\": \"Северные холмы\",\n      \"segmentKm\": 28,\n      \"km\": 245,\n      \"steps\": 326667,\n      \"stepsSincePrevious\": 9334,\n      \"text\": \"С Северных холмов открывается просторный вид на пустоши, уходящие к самому горизонту. На каменистой гряде можно перевести дух и послушать, как ветер шелестит вереском.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-004.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-004-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"lonelylands-005\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 5,\n      \"title\": \"Узкая лесная тропа\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"segmentKm\": 6.6,\n      \"km\": 251.6,\n      \"steps\": 335467,\n      \"stepsSincePrevious\": 8800,\n      \"text\": \"Ежевика почти сомкнулась над узкой лесной тропой, цепляясь за плащ и дорожную сумку. Лишь старая зарубка на стволе помогает отыскать проход между зарослями.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-005.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-005-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-006\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 6,\n      \"title\": \"Поляна серых валунов\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"segmentKm\": 13.2,\n      \"km\": 258.2,\n      \"steps\": 344267,\n      \"stepsSincePrevious\": 8800,\n      \"text\": \"Серые валуны окружили сухую поляну, надёжно укрытую от ветра. На одном из камней остались следы давнего костра — кто-то уже находил здесь приют.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-006.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-006-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-007\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 7,\n      \"title\": \"Болотистая низина\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"segmentKm\": 19.8,\n      \"km\": 264.8,\n      \"steps\": 353067,\n      \"stepsSincePrevious\": 8800,\n      \"text\": \"Земля под ногами становится мягкой и зыбкой, а трава скрывает тёмные лужицы. Дальше приходится нащупывать твёрдую тропу посохом, выбирая каждый шаг.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-007.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-007-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-008\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 8,\n      \"title\": \"Край Комариных топей\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"segmentKm\": 26.4,\n      \"km\": 271.4,\n      \"steps\": 361867,\n      \"stepsSincePrevious\": 8800,\n      \"text\": \"У края Комариных топей воздух наполняется настойчивым звоном насекомых. В сыром песке у воды отпечатались тонкие следы болотных птиц.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-008.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-008-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-009\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 9,\n      \"title\": \"Комариные топи\",\n      \"type\": \"Локация\",\n      \"segment\": 13,\n      \"from\": \"Северные холмы\",\n      \"to\": \"Комариные топи\",\n      \"segmentKm\": 33,\n      \"km\": 278,\n      \"steps\": 370667,\n      \"stepsSincePrevious\": 8800,\n      \"text\": \"Комариные топи встречают путника кваканьем лягушек и целыми тучами комаров. Даже короткий привал здесь превращается в смешное сражение, за которое полагается звание «Гроза комаров».\",\n      \"reward\": {\n        \"id\": \"lonelylands-009-reward\",\n        \"name\": \"Гроза комаров\",\n        \"kind\": \"Достижение\",\n        \"icon\": \"✧\",\n        \"description\": \"\",\n        \"cardText\": \"Достижение · Гроза комаров\",\n        \"badgePrompt\": \"Небольшой круглый латунный значок с огромным комаром и маленькой фигуркой путника, лёгкий добродушный юмор, как гравюра.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Достижение · Гроза комаров\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Небольшой круглый латунный значок с огромным комаром и маленькой фигуркой путника, лёгкий добродушный юмор, как гравюра.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-009.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-009-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"lonelylands-010\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 10,\n      \"title\": \"Кочки среди болот\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 8.67,\n      \"km\": 286.67,\n      \"steps\": 382227,\n      \"stepsSincePrevious\": 11560,\n      \"text\": \"Среди болот приходится перепрыгивать с кочки на кочку, стараясь не угодить в тёмную воду. Одна из них предательски уходит под ногой, и сапог немедленно наполняется холодной жижей.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-010.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-010-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-011\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 11,\n      \"title\": \"Сухая гряда\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 17.33,\n      \"km\": 295.33,\n      \"steps\": 393773,\n      \"stepsSincePrevious\": 11546,\n      \"text\": \"Посреди сырой низины наконец поднимается сухая гряда, где можно разложить промокшие вещи. На песчаном склоне тянется цепочка свежих звериных следов.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-011.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-011-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-012\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 12,\n      \"title\": \"Одинокий путевой столб\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 26,\n      \"km\": 304,\n      \"steps\": 405333,\n      \"stepsSincePrevious\": 11560,\n      \"text\": \"Одинокий путевой столб покосился под ветрами и почти утратил свои надписи. Лишь вырезанные на древесине зарубки ещё подсказывают направление старой дороги.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-012.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-012-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-013\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 13,\n      \"title\": \"Ручей у пустошей\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 34.67,\n      \"km\": 312.67,\n      \"steps\": 416893,\n      \"stepsSincePrevious\": 11560,\n      \"text\": \"У прозрачного ручья удобно наполнить флягу и отдохнуть в тени берега. Под водой блестят гладкие камешки, а впереди постепенно проступают безлюдные просторы.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-013.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-013-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-014\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 14,\n      \"title\": \"Ночь под открытым небом\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 43.33,\n      \"km\": 321.33,\n      \"steps\": 428440,\n      \"stepsSincePrevious\": 11547,\n      \"text\": \"Ночью в пустошах не видно ни одного чужого огонька, зато над головой раскрывается бесконечное звёздное небо. Небольшой костёр становится единственным островком тепла среди темноты.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-014.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-014-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-015\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 15,\n      \"title\": \"Пустоши Эриадора\",\n      \"type\": \"Локация\",\n      \"segment\": 14,\n      \"from\": \"Комариные топи\",\n      \"to\": \"Пустоши Эриадора\",\n      \"segmentKm\": 52,\n      \"km\": 330,\n      \"steps\": 440000,\n      \"stepsSincePrevious\": 11560,\n      \"text\": \"Пустоши Эриадора простираются до горизонта, пряча в высокой траве остатки давних дорог. Возле одинокой каменной кладки виднеется узкая расщелина, которая может скрывать старый путевой тайник.\",\n      \"reward\": {\n        \"id\": \"lonelylands-015-reward\",\n        \"name\": \"Реликвия путника\",\n        \"kind\": \"Секрет\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Секрет · Реликвия путника\",\n        \"badgePrompt\": \"Узкая серебряная дорожная брошь с листовым узором, потускневший металл, следы земли и времени.\",\n        \"conditional\": true,\n        \"condition\": {\n          \"branchId\": \"CAVE-02\",\n          \"requires\": \"completed\"\n        }\n      },\n      \"rewardSource\": \"Секрет · Реликвия путника\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Узкая серебряная дорожная брошь с листовым узором, потускневший металл, следы земли и времени.\",\n      \"optionalBranch\": {\n        \"id\": \"CAVE-02\",\n        \"enabled\": false,\n        \"triggerEventId\": \"lonelylands-015\",\n        \"extraKm\": 5,\n        \"extraSteps\": 6667,\n        \"rewardText\": \"Секрет · «Реликвия путника» — Старинная дорожная брошь, найденная в потайной расщелине.\",\n        \"badgePrompt\": \"Узкая серебряная дорожная брошь с листовым узором, потускневший металл, следы земли и времени.\"\n      },\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-015.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-015-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    },\n    {\n      \"id\": \"lonelylands-016\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 16,\n      \"title\": \"Равнина старых дорог\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 8,\n      \"km\": 338,\n      \"steps\": 450667,\n      \"stepsSincePrevious\": 10667,\n      \"text\": \"Сквозь траву проступают ровные ряды камней — всё, что осталось от широкой дороги исчезнувшего королевства. На миг легко представить повозки и путников, некогда проходивших здесь.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-016.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-016-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-017\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 17,\n      \"title\": \"Плоские каменные плиты\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 16,\n      \"km\": 346,\n      \"steps\": 461333,\n      \"stepsSincePrevious\": 10666,\n      \"text\": \"На пустоши лежат широкие каменные плиты, собранные в неровную площадку. Вереск пробился сквозь трещины, а на крайнем камне сохранился почти стёртый резной знак.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-017.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-017-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-018\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 18,\n      \"title\": \"Дальний силуэт холмов\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 24,\n      \"km\": 354,\n      \"steps\": 472000,\n      \"stepsSincePrevious\": 10667,\n      \"text\": \"Далеко впереди над линией холмов поднимается знакомый одинокий силуэт Заветери. Путник останавливается, чтобы набросать её очертания в дорожном альбоме.\",\n      \"reward\": {\n        \"id\": \"lonelylands-018-reward\",\n        \"name\": \"Заветерь на горизонте\",\n        \"kind\": \"Находка\",\n        \"icon\": \"❧\",\n        \"description\": \"\",\n        \"cardText\": \"Находка · Заветерь на горизонте\",\n        \"badgePrompt\": \"Листок дорожного альбома с карандашным пейзажем далёкого холма и развалин башни, мягкие штрихи графита.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Находка · Заветерь на горизонте\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Листок дорожного альбома с карандашным пейзажем далёкого холма и развалин башни, мягкие штрихи графита.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-018.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-018-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-019\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 19,\n      \"title\": \"Подножие Заветери\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 32,\n      \"km\": 362,\n      \"steps\": 482667,\n      \"stepsSincePrevious\": 10667,\n      \"text\": \"У подножия Заветери тропа круто поднимается между каменными обломками. В траве попадаются тёсаные глыбы, когда-то составлявшие стены башни на вершине.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-019.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-019-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-020\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 20,\n      \"title\": \"След ночного дозора\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 40,\n      \"km\": 370,\n      \"steps\": 493333,\n      \"stepsSincePrevious\": 10666,\n      \"text\": \"Под нависающим камнем сохранились угли старого кострища — когда-то здесь прятались от ветра дозорные или странники. Место и сегодня кажется подходящим для осторожного ночлега.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-020.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-020-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-021\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 21,\n      \"title\": \"Ворон над холмом\",\n      \"type\": \"Путевая заметка\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 48,\n      \"km\": 378,\n      \"steps\": 504000,\n      \"stepsSincePrevious\": 10667,\n      \"text\": \"Над холмом медленно кружит чёрный ворон, не сводящий глаз с развалин. Между камнями обнаруживаются истёртые временем ступени, ведущие выше по склону.\",\n      \"reward\": null,\n      \"rewardSource\": null,\n      \"editorialStatus\": \"Проработать\",\n      \"extendedText\": null,\n      \"badgePrompt\": null,\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-021.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-021-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": false\n    },\n    {\n      \"id\": \"lonelylands-022\",\n      \"chapterId\": \"lonelylands\",\n      \"order\": 22,\n      \"title\": \"Заветерь\",\n      \"type\": \"Глава\",\n      \"segment\": 15,\n      \"from\": \"Пустоши Эриадора\",\n      \"to\": \"Заветерь\",\n      \"segmentKm\": 56,\n      \"km\": 386,\n      \"steps\": 514667,\n      \"stepsSincePrevious\": 10667,\n      \"text\": \"На вершине Заветери под ветром темнеют руины Амон Сул, древней сторожевой башни. Отсюда видны дороги и пустоши на много миль вокруг, словно прежние дозорные всё ещё несут свою службу.\",\n      \"reward\": {\n        \"id\": \"lonelylands-022-reward\",\n        \"name\": \"Дозор Амон Сул\",\n        \"kind\": \"Достижение\",\n        \"icon\": \"✧\",\n        \"description\": \"\",\n        \"cardText\": \"Достижение · Дозор Амон Сул\",\n        \"badgePrompt\": \"Бронзовый круглый медальон с силуэтом древней разрушенной башни на холме, по краю рельефные камни, без письмен.\",\n        \"conditional\": false,\n        \"condition\": null\n      },\n      \"rewardSource\": \"Достижение · Дозор Амон Сул\",\n      \"editorialStatus\": \"Согласовать\",\n      \"extendedText\": null,\n      \"badgePrompt\": \"Бронзовый круглый медальон с силуэтом древней разрушенной башни на холме, по краю рельефные камни, без письмен.\",\n      \"optionalBranch\": null,\n      \"image\": \"assets/illustrations/lonely-lands/lonelylands-022.webp\",\n      \"thumbnail\": \"assets/illustrations/lonely-lands/lonelylands-022-thumb.webp\",\n      \"imageAvailable\": true,\n      \"placeholder\": \"assets/illustrations/hills.svg\",\n      \"isMajor\": true\n    }\n  ]\n}");
